<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Delete, ArrowRight, DocumentChecked, Refresh, Printer } from '@element-plus/icons-vue'
import { api, query } from '../api'
import { useApp } from '../store'
import { today, money, quantity, statusLabels, statusType, itemModule, dateTime } from '../utils'
import DataTable from './DataTable.vue'
import TrialBanner from './TrialBanner.vue'
const app = useApp(), busy = ref(false), saving = ref(false), detailTab = ref('items'), sourceOpen = ref(false), sourceKind = ref(''), sourceSearch = ref(''), sourceRows = ref<any[]>([]), sourceBusy = ref(false)
const refs = reactive<Record<string, any[]>>({ product: [], customer: [], supplier: [], warehouse: [], location: [], employee: [] })
const form = reactive<any>({ id: 0, kind: '', status: 'draft', date: today(), due_date: '', partner_id: undefined, warehouse_id: undefined, target_warehouse_id: undefined, source_id: 0, source_number: '', number: '', revision: 0, amount: '', data: {}, items: [] })
const detail = ref<any>({ transactions: [], related: [], history: [] })
const spec = computed(() => app.kinds.find(k => k.key === form.kind) || { key: form.kind, name: form.kind === 'reversal' ? '红冲凭证' : '业务单据', module: itemModule(form.kind), items: true })
const editable = computed(() => form.status === 'draft' && app.can(spec.value.module + '.edit') && app.writable(spec.value.module))
const canApprove = computed(() => app.can(spec.value.module + '.approve') && app.writable(spec.value.module))
const isPosted = computed(() => ['approved', 'completed', 'in_progress', 'closed'].includes(form.status))
const isOrder = computed(() => ['purchase_order', 'sales_order'].includes(form.kind))
const dualFlow = computed(() => ['purchase_exchange', 'sales_exchange', 'assembly', 'split'].includes(form.kind))
const isCount = computed(() => form.kind === 'inventory_check')
const returnType = computed(() => ['purchase_return', 'sales_return', 'purchase_exchange', 'sales_exchange', 'consignment_settlement', 'consignment_return'].includes(form.kind))
const salesPricing = computed(() => spec.value.module === 'sales' && form.kind !== 'consignment_return')
const conversionMap: Record<string, string[]> = { purchase_order: ['purchase_receipt'], sales_order: ['sales_delivery'], purchase_receipt: ['purchase_return', 'purchase_exchange'], purchase_exchange: ['purchase_return', 'purchase_exchange'], sales_delivery: ['sales_return', 'sales_exchange'], retail_sale: ['sales_return', 'sales_exchange'], sales_exchange: ['sales_return', 'sales_exchange'], consignment_ship: ['consignment_settlement', 'consignment_return'], consignment_settlement: ['sales_return', 'sales_exchange'] }
const sourceKinds = computed(() => Object.entries(conversionMap).filter(([, values]) => values.includes(form.kind)).map(([key]) => app.kinds.find(k => k.key === key)).filter(Boolean))
const conversions = computed(() => isPosted.value && form.kind !== 'reversal' ? (conversionMap[form.kind] || []).filter(k => app.can(itemModule(k) + '.edit')) : [])
const partnerRows = computed(() => spec.value.party === 'supplier' ? refs.supplier : refs.customer)
const displayedTotal = computed(() => {
  if (!spec.value.items || !editable.value) return form.amount
  return form.items.reduce((sum: number, it: any) => { const negative = ['purchase_return', 'sales_return'].includes(form.kind) || form.kind === 'purchase_exchange' && it.flow === 'out' || form.kind === 'sales_exchange' && it.flow === 'in'; return sum + Number(it.quantity || 0) * Number(it.price || 0) * (negative ? -1 : 1) }, 0)
})
const locations = (warehouse: any) => refs.location.filter(l => l.data.warehouse_id === warehouse)
const product = (id: number) => refs.product.find(p => p.id === id)
const kindName = (kind: string) => app.kinds.find(k => k.key === kind)?.name || (kind === 'reversal' ? '红冲凭证' : kind)
const isReturnLine = (it: any) => ['purchase_return', 'sales_return'].includes(form.kind) || form.kind === 'purchase_exchange' && it.flow === 'out' || form.kind === 'sales_exchange' && it.flow === 'in'
const priceDisabled = (it: any) => !editable.value || isReturnLine(it) || salesPricing.value && !app.can('price.override')
function blank(kind: string) { return { id: 0, kind, status: 'draft', date: today(), due_date: '', partner_id: undefined, warehouse_id: refs.warehouse.find(w => !w.data.consignment)?.id, target_warehouse_id: undefined, source_id: 0, source_number: '', number: '', revision: 0, amount: '', note: '', data: { cash_sale: kind === 'retail_sale' }, items: [] } }
async function loadRefs() { const allowed = ['product', 'customer', 'supplier', 'warehouse', 'location', 'employee']; await Promise.all(allowed.map(async k => { refs[k] = (await api('/masters/' + k + '?active=true')).items })) }
function normalizeItems() { form.items = (form.items || []).map((it: any) => ({ ...it, serial_text: (it.serials || []).join('\n'), quantity: String(it.quantity ?? '1'), price: it.price === null || it.price === undefined ? '' : String(it.price) })) }
async function openEditor() { if (!app.editor.visible) return; busy.value = true; detailTab.value = 'items'; try { await loadRefs(); if (app.editor.id) { detail.value = await api('/documents/' + app.editor.id); Object.assign(form, detail.value.document); normalizeItems() } else { Object.assign(form, blank(app.editor.kind)); detail.value = { transactions: [], related: [], history: [] }; if (app.editor.preset) { Object.assign(form, JSON.parse(JSON.stringify(app.editor.preset))); normalizeItems() } else if (spec.value.items && !returnType.value) addItem() } } catch { app.editor.visible = false } finally { busy.value = false } }
watch(() => [app.editor.visible, app.editor.id, app.editor.kind, app.editor.preset], openEditor)
function addItem(flow?: string) { form.items.push({ product_id: undefined, location_id: 0, target_location_id: 0, source_item_id: 0, batch: '', serial_text: '', serials: [], quantity: isCount.value ? '0' : '1', price: '', flow: flow || (dualFlow.value ? 'out' : ''), note: '', price_source: '' }) }
async function chooseProduct(it: any) { const p = product(it.product_id); if (!p) return; it.product_name = p.name; it.product_code = p.code; it.unit = p.data.unit; it.price = ''; it.price_source = ''; if (!salesPricing.value || isReturnLine(it)) it.price = String(p.data.purchase_price ?? '0'); else await quote(it) }
async function quote(it: any) { if (!it.product_id || !salesPricing.value || isReturnLine(it) || Number(it.quantity) <= 0) return; try { const result = await api('/prices/quote?' + query({ product_id: it.product_id, customer_id: form.partner_id || 0, quantity: it.quantity, date: form.date, channel: form.kind === 'retail_sale' ? 'retail' : 'wholesale' })); it.price = result.price; it.price_source = result.source } catch {} }
async function quoteAll() { for (const it of form.items) await quote(it) }
function inputPayload() { return { kind: form.kind, partner_id: Number(form.partner_id || 0), warehouse_id: Number(form.warehouse_id || 0), target_warehouse_id: Number(form.target_warehouse_id || 0), source_id: Number(form.source_id || 0), date: form.date, due_date: form.due_date || '', amount: String(form.amount || ''), note: form.note || '', data: form.data || {}, revision: form.revision || 0, items: form.items.map((it: any) => ({ product_id: Number(it.product_id || 0), location_id: Number(it.location_id || 0), target_location_id: Number(it.target_location_id || 0), source_item_id: Number(it.source_item_id || 0), quantity: String(it.quantity || '0'), price: String(it.price ?? ''), batch: it.batch || '', serials: (it.serial_text || '').split(/[\n,，;；]+/).map((s: string) => s.trim()).filter(Boolean), flow: it.flow || '', note: it.note || '' })) } }
async function save(submit = false) { saving.value = true; try { const result = await api('/documents' + (form.id ? '/' + form.id : ''), form.id ? 'PUT' : 'POST', inputPayload()); Object.assign(form, result); normalizeItems(); if (submit) await api('/documents/' + result.id + '/actions/submit', 'POST', {}); ElMessage.success(submit ? '单据已提交审核' : '草稿已保存'); app.changed(); detail.value = await api('/documents/' + result.id); Object.assign(form, detail.value.document); normalizeItems() } catch {} finally { saving.value = false } }
async function action(action: string) { let reason = ''; const labels: Record<string, string> = { approve: '审核入账', reverse: '红冲单据', cancel: '作废单据', close: '关闭订单', reject: '退回草稿', submit: '提交审核' }; try { if (['reverse', 'close'].includes(action)) { const response = await ElMessageBox.prompt(action === 'reverse' ? '系统将生成红冲凭证并保留全部轨迹。有后续库存流水或核销时，需要先处理关联业务。' : '关闭订单将释放未执行的库存占用。', labels[action], { inputPlaceholder: '请填写原因', inputValidator: value => !!value?.trim() || '原因不能为空', confirmButtonText: '确认' }); reason = response.value } else if (['approve', 'cancel'].includes(action)) await ElMessageBox.confirm(action === 'approve' ? '审核后将更新库存或往来账务。请核对商品、数量、价格与往来单位。' : '作废后保留单据记录，不能继续执行。', labels[action], { confirmButtonText: labels[action], type: action === 'approve' ? 'info' : 'warning' }); saving.value = true; const updated = await api('/documents/' + form.id + '/actions/' + action, 'POST', { reason }); Object.assign(form, updated); normalizeItems(); detail.value = await api('/documents/' + form.id); app.changed(); ElMessage.success(labels[action] + '成功') } catch {} finally { saving.value = false } }
async function convert(target: string) { try { const input = await api('/documents/' + form.id + '/convert?target=' + target); app.editor.kind = target; app.editor.id = 0; app.editor.preset = input } catch {} }
async function loadSources() { sourceBusy.value = true; try { const data = await api('/documents?' + query({ kind: sourceKind.value, search: sourceSearch.value, page_size: 200 })); sourceRows.value = data.items.filter((d: any) => ['approved', 'completed', 'in_progress'].includes(d.status)) } catch {} finally { sourceBusy.value = false } }
function chooseSource() { sourceKind.value = sourceKinds.value[0]?.key || ''; sourceSearch.value = ''; sourceOpen.value = true; loadSources() }
async function useSource(row: any) { try { const preset = await api('/documents/' + row.id + '/convert?target=' + form.kind); const existingID = form.id, revision = form.revision, number = form.number; Object.assign(form, blank(form.kind), preset, { id: existingID, revision, number, source_number: row.number }); normalizeItems(); sourceOpen.value = false } catch {} }
async function countWarehouse() { if (!form.warehouse_id) return; try { if (form.items.some((i: any) => i.product_id)) await ElMessageBox.confirm('将根据所选仓库的当前库存生成盘点明细，替换当前明细。', '提取账面库存'); const result = await api('/inventory/balances?warehouse_id=' + form.warehouse_id); form.items = result.items.map((s: any) => ({ product_id: s.product_id, product_name: s.product_name, location_id: s.location_id, target_location_id: 0, quantity: s.quantity, book_quantity: s.quantity, price: s.avg_cost || '', batch: s.batch, serial_text: '', flow: '', note: '' })); if (!form.items.length) addItem(); if (form.items.length > 200) { form.items = form.items.slice(0, 200); ElMessage.warning('已提取前 200 个库存维度，其余请另建盘点单') } } catch {} }
async function printDoc() { const win = window.open('', '_blank'); if (!win) { ElMessage.warning('请允许弹出打印窗口'); return }; const text = (value: any) => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]!)); const lines = form.items.map((it: any, index: number) => `<tr><td>${index + 1}</td><td>${text(it.product_code)}</td><td>${text(it.product_name)}</td><td>${text(it.batch)}</td><td>${text(it.quantity)}</td>${app.amountVisible ? `<td>${text(it.price)}</td><td>${text(it.amount)}</td>` : ''}</tr>`).join(''); win.document.write(`<!doctype html><html lang="zh-CN"><title>${text(form.number)}</title><style>@font-face{font-family:'Noto Sans SC';src:url('${location.origin}/fonts/NotoSansSC.ttf') format('truetype');font-weight:100 900}body{font:13px 'Noto Sans SC',sans-serif;padding:30px;color:#222}h1{text-align:center;font-size:23px}h2{text-align:center;font-size:17px}table{width:100%;border-collapse:collapse;margin:24px 0}td,th{border:1px solid #bbb;padding:9px;text-align:left}.meta{line-height:2.1;display:flex;justify-content:space-between}.total{text-align:right;font-size:17px}footer{margin-top:50px;display:flex;justify-content:space-between}</style><h1>${text(app.company)}</h1><h2>${text(spec.value.name)}</h2><div class="meta"><span>单号：${text(form.number)}<br>单位：${text(form.partner_name)}<br>仓库：${text(form.warehouse_name)}</span><span>日期：${text(form.date)}<br>状态：${text(statusLabels[form.status])}<br>来源：${text(form.source_number)}</span></div>${spec.value.items ? `<table><thead><tr><th>序号</th><th>商品编码</th><th>商品名称</th><th>批次</th><th>数量</th>${app.amountVisible ? '<th>单价</th><th>金额</th>' : ''}</tr></thead><tbody>${lines}</tbody></table>` : ''}${app.amountVisible ? `<p class="total">合计：¥ ${text(money(form.amount))}</p>` : ''}<p>备注：${text(form.note)}</p><footer><span>制单：${text(form.creator)}</span><span>审核：________________</span><span>签收：________________</span></footer></html>`); win.document.close(); await win.document.fonts.load('13px \"Noto Sans SC\"'); await win.document.fonts.ready; if (!win.closed) win.print() }
</script>
<template>
  <el-drawer v-model="app.editor.visible" size="min(1180px, 96vw)" destroy-on-close :close-on-click-modal="false"><template #header><div><div class="doc-title"><h2>{{ spec.name }}</h2><el-tag :type="statusType(form.status)" size="small">{{ statusLabels[form.status] }}</el-tag></div><div class="doc-number">{{ form.number || '保存时自动生成单据编号' }}<template v-if="form.creator"> · 制单人 {{ form.creator }}</template></div></div></template>
  <TrialBanner class="mb16"/>
  <div v-loading="busy"><el-alert v-if="form.source_id" class="mb16" type="info" :closable="false" :title="'关联原单：' + (form.source_number || form.source_id)" description="执行与退货数量按原单累计校验，退回商品沿用原单价格。"/><el-form label-position="top" :disabled="!editable"><div class="form-grid"><el-form-item label="业务日期 *"><el-date-picker v-model="form.date" type="date" value-format="YYYY-MM-DD" :clearable="false"/></el-form-item><el-form-item v-if="spec.party" :label="(spec.party === 'supplier' ? '供应商' : '客户') + ' *'"><el-select v-model="form.partner_id" filterable placeholder="请选择往来单位" :disabled="!!form.source_id" @change="quoteAll"><el-option v-for="r in partnerRows" :key="r.id" :value="r.id" :label="r.code + ' · ' + r.name"/></el-select></el-form-item><el-form-item v-if="spec.items" :label="spec.target ? '调出仓库 *' : '业务仓库 *'"><el-select v-model="form.warehouse_id" filterable placeholder="请选择仓库"><el-option v-for="r in refs.warehouse" :key="r.id" :value="r.id" :label="r.name + (r.data.consignment ? '（委托仓）' : '')"/></el-select></el-form-item><el-form-item v-if="spec.target" label="调入仓库 *"><el-select v-model="form.target_warehouse_id" filterable placeholder="请选择调入仓库"><el-option v-for="r in refs.warehouse.filter(w => w.id !== form.warehouse_id)" :key="r.id" :value="r.id" :label="r.name + (r.data.consignment ? '（委托仓）' : '')"/></el-select></el-form-item><el-form-item v-if="spec.party" label="到期日期"><el-date-picker v-model="form.due_date" type="date" value-format="YYYY-MM-DD" placeholder="留空按往来单位账期计算"/></el-form-item><el-form-item v-if="spec.items" label="负责业务员"><el-select v-model="form.data.employee_id" filterable clearable placeholder="未指定"><el-option v-for="r in refs.employee" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item><el-form-item v-if="!spec.items && app.amountVisible" label="金额 *"><el-input v-model="form.amount" inputmode="decimal" placeholder="请输入金额"><template #prefix>¥</template></el-input></el-form-item><el-form-item v-if="['sales_delivery','retail_sale','consignment_settlement','sales_exchange'].includes(form.kind)" label="结算方式"><el-checkbox v-model="form.data.cash_sale">现销，同时生成收款单</el-checkbox></el-form-item><el-form-item class="wide" label="业务备注"><el-input v-model="form.note" placeholder="填写业务说明、交货要求或经办信息" maxlength="1000"/></el-form-item></div></el-form>
  <el-tabs v-model="detailTab"><el-tab-pane :label="spec.items ? '商品明细' : '资金信息'" name="items"/><el-tab-pane v-if="form.id" :label="'库存流水 ' + detail.transactions.length" name="transactions"/><el-tab-pane v-if="form.id" :label="'关联单据 ' + detail.related.length" name="related"/><el-tab-pane v-if="form.id" label="操作轨迹" name="history"/></el-tabs>
  <template v-if="detailTab === 'items'"><div v-if="spec.items" class="doc-lines"><div v-if="editable" class="doc-toolbar"><div class="flex gap8"><el-button v-if="!returnType || dualFlow" :icon="Plus" @click="addItem()">添加商品</el-button><el-button v-if="dualFlow" :icon="Plus" @click="addItem('in')">添加入库行</el-button><el-button v-if="sourceKinds.length" plain type="primary" @click="chooseSource">选择来源单据</el-button><el-button v-if="isCount" @click="countWarehouse">提取账面库存</el-button></div><span class="muted text-small">数量 / 单价支持 4 位小数</span></div><div v-if="returnType && !form.source_id" class="hint-box mb16">请先选择来源单据，系统会带入剩余可执行 / 可退商品。换货请另加换入或换出行。</div>
    <el-table :data="form.items" border :max-height="500"><template #empty><el-empty description="选择来源单据或添加商品明细" :image-size="65"/></template><el-table-column type="index" label="#" width="42"/><el-table-column v-if="dualFlow" label="方向" width="90"><template #default="{ row }"><el-select v-model="row.flow" :disabled="!editable || !!row.source_item_id"><el-option label="出库" value="out"/><el-option label="入库" value="in"/></el-select></template></el-table-column><el-table-column label="商品 *" min-width="205"><template #default="{ row }"><el-select v-if="editable && !row.source_item_id" v-model="row.product_id" filterable placeholder="选择商品 / 搜索编码" @change="chooseProduct(row)"><el-option v-for="p in refs.product" :key="p.id" :value="p.id" :label="p.code + ' · ' + p.name"/></el-select><div v-else><b style="font-weight:500">{{ row.product_name || product(row.product_id)?.name }}</b><small class="muted" style="display:block;font-size:10px">{{ row.product_code || product(row.product_id)?.code }} · {{ row.unit || product(row.product_id)?.data.unit }}</small></div></template></el-table-column><el-table-column :label="isCount ? '实盘数量 *' : '数量 *'" width="112" align="right"><template #default="{ row }"><el-input v-if="editable" v-model="row.quantity" inputmode="decimal" @change="quote(row)"/><span v-else>{{ quantity(row.quantity) }}</span></template></el-table-column><el-table-column v-if="isCount" label="账面数量" width="95" align="right"><template #default="{ row }">{{ quantity(row.book_quantity) }}</template></el-table-column><el-table-column v-if="app.amountVisible" :label="['assembly','split'].includes(form.kind) ? '分摊参考价' : '单价'" width="120" align="right"><template #default="{ row }"><el-input v-if="editable" v-model="row.price" inputmode="decimal" :disabled="priceDisabled(row)" placeholder="自动定价"/><span v-else>{{ quantity(row.price) }}</span><span v-if="row.price_source" style="font-size:9px;color:#98a8be;display:block;margin-top:3px">{{ row.price_source }}</span></template></el-table-column><el-table-column v-if="app.amountVisible" label="金额" width="115" align="right"><template #default="{ row }">{{ money(editable ? Number(row.quantity || 0) * Number(row.price || 0) : row.amount) }}</template></el-table-column><el-table-column label="库位" width="130"><template #default="{ row }"><el-select v-if="editable" v-model="row.location_id" filterable><el-option label="默认库位" :value="0"/><el-option v-for="r in locations(form.warehouse_id)" :key="r.id" :value="r.id" :label="r.name"/></el-select><span v-else>{{ refs.location.find(l => l.id === row.location_id)?.name || '默认库位' }}</span></template></el-table-column><el-table-column v-if="spec.target" label="调入库位" width="130"><template #default="{ row }"><el-select v-model="row.target_location_id" :disabled="!editable"><el-option label="默认库位" :value="0"/><el-option v-for="r in locations(form.target_warehouse_id)" :key="r.id" :value="r.id" :label="r.name"/></el-select></template></el-table-column><el-table-column label="批次" width="120"><template #default="{ row }"><el-input v-if="editable" v-model="row.batch" :disabled="!!row.source_item_id" :placeholder="product(row.product_id)?.data.batch_tracking ? '必填批次' : '可选'"/><span v-else>{{ row.batch || '—' }}</span></template></el-table-column><el-table-column label="序列号" width="150"><template #default="{ row }"><el-popover trigger="click" width="300" placement="left"><template #reference><el-button link type="primary">{{ row.serial_text ? row.serial_text.split('\n').filter(Boolean).length + ' 个序列号' : '填写 / 查看' }}</el-button></template><p class="muted mb16">每行一个序列号；盘点仅填写差异涉及的序列号。</p><el-input v-model="row.serial_text" type="textarea" :rows="7" :disabled="!editable" placeholder="每行一个序列号"/></el-popover></template></el-table-column><el-table-column v-if="editable" width="48" fixed="right"><template #default="{ $index }"><el-button link type="danger" :icon="Delete" aria-label="删除明细" @click="form.items.splice($index, 1)"/></template></el-table-column></el-table>
    <div class="doc-total"><span>共 {{ form.items.length }} 行</span><span>合计数量 <b>{{ quantity(form.items.reduce((sum: number, it: any) => sum + Number(it.quantity || 0), 0)) }}</b></span><span v-if="app.amountVisible">{{ editable ? '预估合计' : '单据合计' }}<strong>¥ {{ money(displayedTotal) }}</strong></span></div><p v-if="editable" class="muted text-small mt16">保存时会按服务端精度规则计算正式金额。组装 / 拆分的实际成本按出库成本分摊，参考价仅用于产出权重。</p>
  </div><div v-else class="hint-box">{{ form.kind.startsWith('opening') ? '期初往来独立记录，请在该往来单位正式业务开始前录入。正数代表应收 / 应付，负数代表贷项余额。' : form.kind.endsWith('refund') ? '退款先核销退货贷项，剩余金额抵扣可用预收 / 预付余额，不允许超额退款。' : '审核后按到期日自动核销同一往来单位的应收 / 应付，剩余金额作为预收 / 预付。可在往来管理中继续部分或批量核销。' }}</div></template>
  <DataTable v-if="detailTab === 'transactions'" :rows="detail.transactions" :columns="[{ key:'warehouse_name',label:'仓库' },{ key:'product_name',label:'商品',minWidth:150 },{ key:'batch',label:'批次' },{ key:'before_quantity',label:'变动前',type:'qty' },{ key:'delta',label:'变动数量',type:'qty' },{ key:'after_quantity',label:'变动后',type:'qty' },{ key:'cost_delta',label:'成本变动',type:'money',hidden:!app.costVisible },{ key:'operator',label:'操作人' }]" empty="本单尚未生成库存流水"/>
  <DataTable v-if="detailTab === 'related'" :rows="detail.related.map((r: any) => ({ ...r, kind_name:kindName(r.kind) }))" :columns="[{ key:'number',label:'关联单号',type:'link',minWidth:220 },{ key:'kind_name',label:'业务类型' },{ key:'status',label:'状态',type:'status' },{ key:'amount',label:'金额',type:'money',hidden:!app.amountVisible }]" @open="id => app.openDoc(id)"/>
  <div v-if="detailTab === 'history'" class="panel-body"><el-timeline><el-timeline-item v-for="(h, i) in detail.history" :key="i" :timestamp="dateTime(h.created_at)" color="#6393e3"><strong>{{ h.username }} · {{ h.action }}</strong><p v-if="h.after_data?.reason" class="muted mt16">{{ h.after_data.reason }}</p></el-timeline-item></el-timeline></div>
  </div><template #footer><div class="doc-footer"><span v-if="form.id" class="muted text-small" style="margin-right:auto">审核后锁定明细，所有变动留有记录</span><el-button @click="app.editor.visible = false">关闭</el-button><el-button v-if="form.id" :icon="Printer" @click="printDoc">打印</el-button><el-button v-if="editable" :loading="saving" @click="save()">保存草稿</el-button><el-button v-if="editable" type="primary" :loading="saving" @click="save(true)">保存并提交</el-button><el-button v-if="form.status === 'submitted' && app.can(spec.module + '.edit') && app.writable(spec.module)" :loading="saving" @click="action('reject')">退回草稿</el-button><el-button v-if="form.status === 'submitted' && canApprove" type="primary" :icon="DocumentChecked" :loading="saving" @click="action('approve')">审核入账</el-button><el-button v-if="['draft','submitted'].includes(form.status) && form.id && app.can(spec.module + '.edit') && app.writable(spec.module)" text type="danger" :loading="saving" @click="action('cancel')">作废</el-button><el-dropdown v-if="conversions.length && app.writable(spec.module)" trigger="click" @command="convert"><el-button type="primary">生成下游单据 <el-icon><ArrowRight/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="target in conversions" :key="target" :command="target">{{ kindName(target) }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button v-if="isPosted && isOrder && form.status !== 'closed' && app.can(spec.module + '.edit') && app.writable(spec.module)" :loading="saving" @click="action('close')">关闭订单</el-button><el-button v-if="isPosted && !['reversal'].includes(form.kind) && canApprove" plain type="danger" :loading="saving" @click="action('reverse')">红冲</el-button></div></template></el-drawer>
  <el-dialog v-model="sourceOpen" title="选择已审核来源单据" width="880px" append-to-body><div class="filter-row" style="padding:0 0 16px"><el-select v-model="sourceKind" @change="loadSources"><el-option v-for="k in sourceKinds" :key="k.key" :label="k.name" :value="k.key"/></el-select><el-input v-model="sourceSearch" placeholder="单号或往来单位" @keyup.enter="loadSources"/><el-button type="primary" @click="loadSources">查询</el-button></div><DataTable :rows="sourceRows" :loading="sourceBusy" :columns="[{key:'number',label:'单号',minWidth:220},{key:'partner_name',label:'往来单位'},{key:'date',label:'日期'},{key:'status',label:'状态',type:'status'}]" @row="useSource"><template #actions="{ row }"><el-button link type="primary" @click="useSource(row)">选择原单</el-button></template></DataTable></el-dialog>
</template>
